import { existsSync } from "node:fs";
import { defineConfig, devices } from "@playwright/test";

// Local test keys (generated by `npm run test:env`, never committed).
if (existsSync(".env.test.local")) process.loadEnvFile(".env.test.local");

/** Visual captures for before / after comparisons (tests/visual); not part of the E2E suite. */
export default defineConfig({
  testDir: "tests/visual",
  workers: 1,
  timeout: 600_000,
  reporter: [["list"]],
  use: { baseURL: process.env.E2E_BASE_URL ?? "http://localhost:3000", ...devices["Desktop Chrome"], trace: "off" },
});
